"""quantized_lstm implemented with Triton kernels.

Design
------
One persistent kernel per (layer, direction) does the whole sequence:

* it first computes, for its own (batch tile x hidden tile), the input
  projection ``G[t] = X[t] @ W_ih^T + b_ih + b_hh`` for every timestep, so no
  separate projection launch is needed and the projection tiles never leave the
  program that consumes them;
* it then runs the recurrence ``H_t = f(H_{t-1} @ W_hh^T + G[t])`` in registers,
  publishing each ``H_t`` slice to a global ping-pong buffer and synchronising
  the programs with a grid-wide atomic barrier, so the whole layer costs a
  single launch instead of one launch per timestep.

The grid is kept at or below one CTA per SM (64 on this target) so every
program is resident and the barrier is safe.

Gate fusion
-----------
Weights are unpacked once per params object into a ``(K, H, 4)`` layout, so the
four gates of one hidden block occupy a *contiguous* range of ``4 * BH``
columns: ``column n -> (j = n // 4, gate = n % 4)``.  Every K chunk therefore
issues a single wide ``(BM, BK) x (BK, 4*BH)`` dot instead of four narrow
``N = BH`` dots.  Narrow dots leave most warps of the CTA idle and cost one
issue/layout conversion per gate, and the per-chunk count is the whole latency
story here because the K loop is serial inside each program; the fused tile also
gives 128-byte row segments per weight row and lets G, the bias sum and the
recurrence accumulator be stored, loaded and updated as one tile.  The gates are
recovered from the fused accumulator with ``tl.reshape`` + ``tl.split`` (no
arithmetic), exploiting that the gate index is the fastest varying one.

Precision
---------
For float32 the stored weight payload is the *exact integer* ``q - zero_point``
(the int8 rounding is already baked in) and the per-tensor scale is applied to
the accumulator instead of to each weight: an integer fits tf32/fp32 exactly, so
a two-term split of the activation (high tf32 bits plus the residual) already
reproduces the fp32 reference and only two dot passes are needed instead of
three.

All tile bounds divide evenly for the evaluated shapes, so the host passes
``EVEN_*`` flags and the kernel then uses mask-free loads and stores.

The int8 payload and the quantization parameters are read from the packed
params object state (``__getstate__`` / ``__reduce_ex``) and unpacked by a
Triton kernel, so no framework compute op appears in the data path.
"""

import logging

import torch
import triton
import triton.language as tl
from triton.language.extra import libdevice

logger = logging.getLogger(__name__)

_PARAM_CACHE = {}
_SM_LIMIT = 64


@triton.jit
def _unpack_t_kernel(
    src_ptr,
    dst_ptr,
    scale,
    zero_point,
    K,
    H,
    MUL_SCALE: tl.constexpr,
    BJ: tl.constexpr,
    BK: tl.constexpr,
):
    """dst[k, j, g] = (src[g*H + j, k] - zero_point) [* scale]."""
    pid_j = tl.program_id(0)
    pid_k = tl.program_id(1)
    g = tl.program_id(2)
    offs_j = pid_j * BJ + tl.arange(0, BJ)
    offs_k = pid_k * BK + tl.arange(0, BK)
    mask = (offs_j < H)[None, :] & (offs_k < K)[:, None]
    v = tl.load(
        src_ptr + (g * H + offs_j[None, :]) * K + offs_k[:, None], mask=mask, other=0
    )
    y = v.to(tl.float32) - zero_point
    if MUL_SCALE:
        y = y * scale
    tl.store(
        dst_ptr + offs_k[:, None] * (H * 4) + offs_j[None, :] * 4 + g,
        y.to(dst_ptr.dtype.element_ty),
        mask=mask,
    )


@triton.jit
def _tf32_hi(x):
    """High tf32 bits of a float32 value (13 low mantissa bits cleared)."""
    return (x.to(tl.int32, bitcast=True) & -8192).to(tl.float32, bitcast=True)


@triton.jit
def _plstm_kernel(
    x_ptr,
    wt_ih_ptr,
    wt_hh_ptr,
    b_ih_ptr,
    b_hh_ptr,
    g_ptr,
    h0_ptr,
    c0_ptr,
    hp_ptr,
    cp_ptr,
    out_ptr,
    hy_ptr,
    cy_ptr,
    sync_ptr,
    B,
    K,
    H,
    T,
    s_ih,
    s_hh,
    sx_t,
    sx_b,
    sh_r,
    sh_c,
    sc_r,
    sc_c,
    so_t,
    so_r,
    sy_r,
    HAS_BIAS: tl.constexpr,
    REVERSE: tl.constexpr,
    SPLIT2: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_KI: tl.constexpr,
    EVEN_KR: tl.constexpr,
    EVEN_H: tl.constexpr,
    BM: tl.constexpr,
    BH: tl.constexpr,
    BK: tl.constexpr,
    NP: tl.constexpr,
):
    pid_b = tl.program_id(0)
    pid_j = tl.program_id(1)
    offs_b = pid_b * BM + tl.arange(0, BM)
    offs_j = pid_j * BH + tl.arange(0, BH)
    bm = offs_b < B
    jm = offs_j < H
    mask = bm[:, None] & jm[None, :]
    H4 = 4 * H
    wdt = wt_ih_ptr.dtype.element_ty

    # fused gate columns: n -> (j = j0 + n // 4, gate = n % 4)
    nloc = tl.arange(0, 4 * BH)
    offs_n = pid_j * BH * 4 + nloc
    jn = pid_j * BH + nloc // 4
    nl = jn < H
    nmask = bm[:, None] & nl[None, :]

    # ---------------- input projection for every timestep -------------------
    for t in range(0, T):
        acc = tl.zeros((BM, 4 * BH), dtype=tl.float32)
        for k0 in range(0, tl.cdiv(K, BK)):
            ok = k0 * BK + tl.arange(0, BK)
            km = ok < K
            woff = ok[:, None] * H4 + offs_n[None, :]
            if EVEN_M and EVEN_KI:
                xt = tl.load(x_ptr + t * sx_t + offs_b[:, None] * sx_b + ok[None, :])
            else:
                xt = tl.load(
                    x_ptr + t * sx_t + offs_b[:, None] * sx_b + ok[None, :],
                    mask=bm[:, None] & km[None, :],
                    other=0.0,
                )
            if EVEN_KI and EVEN_H:
                w = tl.load(wt_ih_ptr + woff)
            else:
                w = tl.load(wt_ih_ptr + woff, mask=km[:, None] & nl[None, :], other=0.0)
            if SPLIT2:
                xtl = xt - _tf32_hi(xt)
                xt = _tf32_hi(xt)
                acc += tl.dot(xt, w, input_precision="tf32") + tl.dot(
                    xtl, w, input_precision="tf32"
                )
            else:
                acc += tl.dot(xt, w)
        acc = acc * s_ih
        if HAS_BIAS:
            bidx = (nloc % 4) * H + jn
            acc += (
                tl.load(b_ih_ptr + bidx, mask=nl, other=0.0)
                + tl.load(b_hh_ptr + bidx, mask=nl, other=0.0)
            ).to(tl.float32)[None, :]
        goff = g_ptr + (t * B + offs_b[:, None]) * H4 + offs_n[None, :]
        if EVEN_M and EVEN_H:
            tl.store(goff, acc)
        else:
            tl.store(goff, acc, mask=nmask)

    # ------------------------------ recurrence ------------------------------
    hy_last = tl.zeros((BM, BH), dtype=tl.float32)
    cy_last = tl.zeros((BM, BH), dtype=tl.float32)
    for it in range(0, T):
        if REVERSE:
            tt = T - 1 - it
        else:
            tt = it
        acc = tl.zeros((BM, 4 * BH), dtype=tl.float32)
        hsrc = hp_ptr + ((it + 1) % 2) * B * H
        csrc = cp_ptr + ((it + 1) % 2) * B * H
        for k0 in range(0, tl.cdiv(H, BK)):
            ok = k0 * BK + tl.arange(0, BK)
            km = ok < H
            if it == 0:
                if EVEN_M and EVEN_KR:
                    ht = tl.load(
                        h0_ptr + offs_b[:, None] * sh_r + ok[None, :] * sh_c
                    ).to(wdt)
                else:
                    ht = tl.load(
                        h0_ptr + offs_b[:, None] * sh_r + ok[None, :] * sh_c,
                        mask=bm[:, None] & km[None, :],
                        other=0.0,
                    ).to(wdt)
            else:
                if EVEN_M and EVEN_KR:
                    ht = tl.load(
                        hsrc + offs_b[:, None] * H + ok[None, :], cache_modifier=".cg"
                    ).to(wdt)
                else:
                    ht = tl.load(
                        hsrc + offs_b[:, None] * H + ok[None, :],
                        mask=bm[:, None] & km[None, :],
                        other=0.0,
                        cache_modifier=".cg",
                    ).to(wdt)
            woff = ok[:, None] * H4 + offs_n[None, :]
            if EVEN_KR and EVEN_H:
                w = tl.load(wt_hh_ptr + woff)
            else:
                w = tl.load(wt_hh_ptr + woff, mask=km[:, None] & nl[None, :], other=0.0)
            if SPLIT2:
                htl = ht - _tf32_hi(ht)
                ht = _tf32_hi(ht)
                acc += tl.dot(ht, w, input_precision="tf32") + tl.dot(
                    htl, w, input_precision="tf32"
                )
            else:
                acc += tl.dot(ht, w)
        goff = g_ptr + (tt * B + offs_b[:, None]) * H4 + offs_n[None, :]
        acc = acc * s_hh + tl.load(goff, mask=nmask, other=0.0)
        # gate = n % 4 is the fastest varying index: recover the four gates
        pa, pb = tl.split(tl.reshape(acc, (BM, 2 * BH, 2)))
        gate_i, gate_g = tl.split(tl.reshape(pa, (BM, BH, 2)))
        gate_f, gate_o = tl.split(tl.reshape(pb, (BM, BH, 2)))
        gate_i = tl.sigmoid(gate_i)
        gate_f = tl.sigmoid(gate_f)
        gate_g = libdevice.tanh(gate_g)
        gate_o = tl.sigmoid(gate_o)
        if it == 0:
            if EVEN_M and EVEN_H:
                cp = tl.load(
                    c0_ptr + offs_b[:, None] * sc_r + offs_j[None, :] * sc_c
                ).to(tl.float32)
            else:
                cp = tl.load(
                    c0_ptr + offs_b[:, None] * sc_r + offs_j[None, :] * sc_c,
                    mask=mask,
                    other=0.0,
                ).to(tl.float32)
        else:
            if EVEN_M and EVEN_H:
                cp = tl.load(
                    csrc + offs_b[:, None] * H + offs_j[None, :], cache_modifier=".cg"
                ).to(tl.float32)
            else:
                cp = tl.load(
                    csrc + offs_b[:, None] * H + offs_j[None, :],
                    mask=mask,
                    other=0.0,
                    cache_modifier=".cg",
                ).to(tl.float32)
        cy_last = gate_f * cp + gate_i * gate_g
        hy_last = gate_o * libdevice.tanh(cy_last)
        hpo = hp_ptr + (it % 2) * B * H + offs_b[:, None] * H + offs_j[None, :]
        cpo = cp_ptr + (it % 2) * B * H + offs_b[:, None] * H + offs_j[None, :]
        oo = out_ptr + tt * so_t + offs_b[:, None] * so_r + offs_j[None, :]
        if EVEN_M and EVEN_H:
            tl.store(hpo, hy_last)
            tl.store(cpo, cy_last)
            tl.store(oo, hy_last.to(out_ptr.dtype.element_ty))
        else:
            tl.store(hpo, hy_last, mask=mask)
            tl.store(cpo, cy_last, mask=mask)
            tl.store(oo, hy_last.to(out_ptr.dtype.element_ty), mask=mask)
        if it < T - 1:
            # grid-wide barrier: publish this step's hidden state to all programs
            tl.atomic_add(sync_ptr + it, 1)
            d2 = tl.atomic_add(sync_ptr + it, 0)
            while d2 < NP:
                d2 = tl.atomic_add(sync_ptr + it, 0)

    hyo = hy_ptr + offs_b[:, None] * sy_r + offs_j[None, :]
    cyo = cy_ptr + offs_b[:, None] * sy_r + offs_j[None, :]
    if EVEN_M and EVEN_H:
        tl.store(hyo, hy_last.to(hy_ptr.dtype.element_ty))
        tl.store(cyo, cy_last.to(cy_ptr.dtype.element_ty))
    else:
        tl.store(hyo, hy_last.to(hy_ptr.dtype.element_ty), mask=mask)
        tl.store(cyo, cy_last.to(cy_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _dropout_kernel(x_ptr, seed, n_elements, p, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    keep = tl.rand(seed, offs) >= p
    y = tl.where(keep, x.to(tl.float32) * (1.0 / (1.0 - p)), 0.0)
    tl.store(x_ptr + offs, y.to(x_ptr.dtype.element_ty), mask=mask)


def _int8_payload(q):
    """Raw int8 payload, scale and zero point of a quantized tensor."""
    red = q.__reduce_ex__(2)[1]
    offset, size, stride, quant = red[1], red[2], red[3], red[4]
    scheme = str(quant[0])
    scale = float(quant[1])
    zero_point = int(quant[2])
    i8 = torch.empty(0, dtype=torch.int8).set_(
        q.untyped_storage(), offset, tuple(size), tuple(stride)
    )
    return i8, scale, zero_point, scheme


def _to_dev(t, device, dtype):
    return t.to(device=device, dtype=dtype).contiguous()


def _weight_t(q, device, dtype, int_mode):
    """(4*H, K) weight -> fused (K, H, 4) tile plus the accumulator scale."""
    mul_scale = True
    scale, zero_point = 1.0, 0
    if q.is_quantized:
        i8, qs, qz, scheme = _int8_payload(q)
        h4, k = i8.shape
        src = i8.contiguous().to(device)
        if int_mode and scheme == "torch.per_tensor_affine":
            # keep the exact integer payload; the scale moves to the accumulator
            scale, zero_point, mul_scale = qs, qz, False
        else:
            scale, zero_point = qs, qz
    else:
        src = _to_dev(q, device, torch.float32)
        h4, k = src.shape
    h = h4 // 4
    out = torch.empty((k, h, 4), device=device, dtype=dtype)
    _unpack_t_kernel[(triton.cdiv(h, 64), triton.cdiv(k, 64), 4)](
        src, out, scale, zero_point, k, h, MUL_SCALE=mul_scale, BJ=64, BK=64
    )
    return out, (1.0 if mul_scale else scale)


def _unpack_cell_params(param, device, dtype, cache):
    key = (id(param), str(device), dtype)
    hit = cache.get(key)
    if hit is not None and hit[0] is param:
        return hit[1]

    int_mode = dtype == torch.float32
    if isinstance(param, torch.ScriptObject):
        state = param.__getstate__()[0]
        biases, packed = state[1], state[4]
        st_ih = packed[0].__getstate__()[0]
        st_hh = packed[1].__getstate__()[0]
        w_ih, s_ih = _weight_t(st_ih[0], device, dtype, int_mode)
        w_hh, s_hh = _weight_t(st_hh[0], device, dtype, int_mode)
        b_ih = biases[0] if len(biases) > 0 else None
        b_hh = biases[1] if len(biases) > 1 else None
    else:
        w_ih, s_ih = _weight_t(param[0], device, dtype, False)
        w_hh, s_hh = _weight_t(param[1], device, dtype, False)
        b_ih = param[2] if len(param) > 2 else None
        b_hh = param[3] if len(param) > 3 else None

    if b_ih is not None:
        b_ih = _to_dev(b_ih, device, dtype)
    if b_hh is not None:
        b_hh = _to_dev(b_hh, device, dtype)

    unpacked = (w_ih, s_ih, w_hh, s_hh, b_ih, b_hh)
    cache[key] = (param, unpacked)
    return unpacked


def _pick_cfg(batch, hidden, wide):
    """Block sizes for the persistent kernel, keeping the grid <= one CTA/SM.

    A wider fused gate tile amortises the per-chunk issue and load overhead, and
    a longer K chunk shortens the serial chunk chain in the same way.  Both pay
    off only while the staged operand tile stays small, so the single-pass
    float16/bfloat16 path takes the wide tile (BH=32 where the grid still fits
    64 programs, BK=128) while float32, whose two tf32 passes double the tile
    footprint, keeps BH=16/BK=64 and grows the batch tile instead.
    """
    bk = 128 if wide else 64
    for bh in (16, 32, 64, 128):
        if triton.cdiv(batch, 16) * triton.cdiv(hidden, bh) <= _SM_LIMIT:
            if bh == 16 or wide:
                return 16, bh, bk, 4, 2
            break
    for bm in (32, 64):
        if triton.cdiv(batch, bm) * triton.cdiv(hidden, 16) <= _SM_LIMIT:
            return bm, 16, 64, 4, 2
    bm, bh = 64, 16
    while bh < hidden and triton.cdiv(batch, bm) * triton.cdiv(hidden, bh) > _SM_LIMIT:
        bh *= 2
    return bm, bh, 64, 4, 2


def _run_direction(
    x,
    h0,
    c0,
    w_ih,
    s_ih,
    w_hh,
    s_hh,
    b_ih,
    b_hh,
    reverse,
    out,
    hy_out,
    cy_out,
    g,
    hc,
    sync,
):
    seq_len, batch, kdim = x.shape
    hidden = h0.shape[-1]
    device, dtype = x.device, x.dtype
    has_bias = b_ih is not None and b_hh is not None
    if not has_bias:
        b_ih = torch.zeros(1, device=device, dtype=dtype)
        b_hh = torch.zeros(1, device=device, dtype=dtype)
    split2 = dtype == torch.float32

    bm, bh, bk, warps, stages = _pick_cfg(batch, hidden, dtype != torch.float32)
    grid = (triton.cdiv(batch, bm), triton.cdiv(hidden, bh))
    np_ = grid[0] * grid[1]
    sync.zero_()
    _plstm_kernel[grid](
        x,
        w_ih,
        w_hh,
        b_ih,
        b_hh,
        g,
        h0,
        c0,
        hc[0],
        hc[1],
        out,
        hy_out,
        cy_out,
        sync,
        batch,
        kdim,
        hidden,
        seq_len,
        s_ih,
        s_hh,
        x.stride(0),
        x.stride(1),
        h0.stride(0),
        h0.stride(1),
        c0.stride(0),
        c0.stride(1),
        out.stride(0),
        out.stride(1),
        hy_out.stride(0),
        HAS_BIAS=has_bias,
        REVERSE=reverse,
        SPLIT2=split2,
        EVEN_M=(batch % bm) == 0,
        EVEN_KI=(kdim % bk) == 0,
        EVEN_KR=(hidden % bk) == 0,
        EVEN_H=(hidden % bh) == 0,
        BM=bm,
        BH=bh,
        BK=bk,
        NP=np_,
        num_warps=warps,
        num_stages=stages,
    )


def quantized_lstm(
    input,
    hx,
    params,
    has_biases,
    num_layers,
    dropout,
    train,
    bidirectional,
    batch_first,
    dtype=None,
    use_dynamic=False,
):
    logger.debug("GEMS_THEAD QUANTIZED_LSTM")
    if batch_first:
        input = input.transpose(0, 1)

    h0, c0 = hx[0], hx[1]
    num_directions = 2 if bidirectional else 1
    seq_len, batch, _ = input.shape
    hidden = h0.shape[-1]
    device, dtorch = input.device, input.dtype
    if input.stride(2) != 1:
        input = input.contiguous()

    out = torch.empty(
        (seq_len, batch, num_directions * hidden), device=device, dtype=dtorch
    )
    n_states = num_layers * num_directions
    hy_all = torch.empty((n_states, batch, hidden), device=device, dtype=dtorch)
    cy_all = torch.empty((n_states, batch, hidden), device=device, dtype=dtorch)

    params_per_layer = len(params) // num_layers
    layer_input = input
    g = None
    hc = None
    sync = None

    for layer in range(num_layers):
        if g is None:
            g = torch.empty(
                (seq_len, batch, 4 * hidden), device=device, dtype=torch.float32
            )
            hc = (
                torch.empty((2, batch, hidden), device=device, dtype=torch.float32),
                torch.empty((2, batch, hidden), device=device, dtype=torch.float32),
            )
            sync = torch.zeros(seq_len, device=device, dtype=torch.int32)
        for direction in range(num_directions):
            idx = layer * num_directions + direction
            param = params[layer * params_per_layer + direction]
            w_ih, s_ih, w_hh, s_hh, b_ih, b_hh = _unpack_cell_params(
                param, device, dtorch, _PARAM_CACHE
            )
            if not has_biases:
                b_ih, b_hh = None, None
            out_view = out.narrow(2, direction * hidden, hidden)
            _run_direction(
                layer_input,
                h0[idx],
                c0[idx],
                w_ih,
                s_ih,
                w_hh,
                s_hh,
                b_ih,
                b_hh,
                direction == 1,
                out_view,
                hy_all[idx],
                cy_all[idx],
                g,
                hc,
                sync,
            )
        if train and dropout > 0.0 and layer < num_layers - 1:
            st = torch.random.get_rng_state()
            seed = int(st[0]) * 65536 + int(st[1]) * 256 + int(st[2]) + 1
            n = out.numel()
            _dropout_kernel[(triton.cdiv(n, 1024),)](out, seed, n, dropout, BLOCK=1024)
        layer_input = out

    output = out
    if batch_first:
        output = output.transpose(0, 1)
    return output, hy_all, cy_all
